<?php
namespace Tests\Feature\InternalGames;
use Tests\TestCase;
use Tests\Support\BlackjackFixture;
use Illuminate\Foundation\Testing\DatabaseTransactions;
use Illuminate\Support\Facades\DB;
use App\Models\{CmsGame,CmsUser,InternalGameSession,InternalGameRound,InternalGameCrashRound,CmsUserTransaction};
use App\Services\InternalGames\{SkyRushEngine,SkyRushService,InternalGameSessionService,InternalGameLedgerAuditService};
class SkyRushIntegrityTest extends TestCase {
 use DatabaseTransactions,BlackjackFixture;
 protected function setUp():void{parent::setUp();$this->setupBlackjack();(new \Database\Seeders\InternalCrashFamilySeeder)->run();$this->travelTo(now()->setMicrosecond(123000));$engine=\Mockery::mock(SkyRushEngine::class)->makePartial();$engine->shouldReceive('createRoundMath')->andReturnUsing(function($def,$id)use($engine){return ['server_seed'=>'deterministic-test-only','server_seed_hash'=>hash('sha256','deterministic-test-only'),'fair_hash'=>hash('sha256','deterministic-test-only|'.$id),'crash_multiplier'=>5,'flight_seconds'=>$engine->secondsForMultiplier($def,5)];});$this->app->instance(SkyRushEngine::class,$engine);}
 protected function tearDown():void{$this->travelBack();parent::tearDown();}
 private function open(string $code='sky-rush',bool $demo=false):InternalGameSession{return app(InternalGameSessionService::class)->launch(CmsGame::where('slug',$code)->firstOrFail(),$this->player,$demo,request());}
 private function svc():SkyRushService{return app(SkyRushService::class);}
 private function snap(InternalGameSession $s):array{return $this->svc()->snapshot($s->session_token,$this->player);}
 private function bet(InternalGameSession $s,int $lane=1,string $key='crash-bet',int $amount=10,?string $expected=null):array{return $this->svc()->placeBet($s->session_token,$this->player,$amount,$key,$lane,$expected);}
 private function phase(InternalGameSession $s,int $ms=1000):InternalGameCrashRound{$r=InternalGameCrashRound::where('cms_game_id',$s->cms_game_id)->where('is_demo',$s->is_demo)->latest('id')->firstOrFail();$this->travelTo($r->starts_at->copy()->addMilliseconds($ms));return $r;}
 private function reject(callable $f,int $status=409):void{try{$f();$this->fail('Expected HTTP '.$status);}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame($status,$e->getStatusCode());}}
 public function test_both_original_definitions_demo_real_two_lanes_cashout_loss_history_and_reconciliation():void{
  foreach(['sky-rush','orbit-x']as $code)foreach([true,false]as $demo){$s=$this->open($code,$demo);$before=$this->financeHash();$snap=$this->snap($s);$this->assertNull($snap['currentRound']['fairHash']);$this->assertNull($snap['currentRound']['crashedAt']);$this->assertNull($snap['currentRound']['revealedServerSeed']);$a=$this->bet($s);$b=$this->bet($s,2,'lane-two');$this->assertSame($a['crashRoundId'],$b['crashRoundId']);$this->phase($s);$win=$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'cashout-one');$this->assertSame('settled_win',$win['status']);$this->assertGreaterThan(10,$win['cashoutAmount']);$this->assertSame((float)$win['balance'],(float)$this->snap($s)['balance']);$this->assertArrayNotHasKey('crashMultiplier',$win['result']);$r=$this->phase($s);$this->travelTo($r->crashed_at->copy()->addMillisecond());$snap=$this->snap($s);$this->assertSame('crashed',$snap['currentRound']['status']);$this->assertNotNull($snap['currentRound']['fairHash']);$this->assertSame(5.0,$snap['currentRound']['crashMultiplier']);$this->assertSame('settled_loss',$snap['myBets']['2']['status']);$this->assertCount(2,$snap['myBetHistory']);$this->assertNotSame($before,$this->financeHash());$this->reconcileBlackjack();$this->travelTo(now()->addMinute());}
 }
 public function test_request_replay_payload_lane_conflict_and_expected_round_are_economically_idempotent():void{$s=$this->open();$a=$this->bet($s);$before=$this->financeHash();$this->assertSame($a,$this->bet($s));$this->reject(fn()=>$this->bet($s,2));$this->reject(fn()=>$this->bet($s,1,'new-key'));$this->reject(fn()=>$this->bet($s,1,'crash-bet',50));$this->reject(fn()=>$this->bet($s,2,'wrong-round',10,'igcr_stale'));$this->assertSame($before,$this->financeHash());$b=$this->bet($s,2,'lane-two');$this->assertNotSame($a['roundId'],$b['roundId']);$this->reconcileBlackjack();}
 public function test_time_boundaries_milliseconds_round_transition_and_late_cashout_never_attaches_old_bet_to_successor():void{$s=$this->open();$a=$this->bet($s);$r=$this->phase($s,0);$this->assertSame(123,$r->starts_at->millisecond);$this->assertGreaterThan(0,$r->crashed_at->millisecond);$this->assertSame('flying',$this->snap($s)['currentRound']['status']);$this->reject(fn()=>$this->bet($s,2,'at-close'));$this->travelTo($r->crashed_at->copy()->subMillisecond());$win=$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'before-crash');$this->assertSame('settled_win',$win['status']);$this->travelTo($r->crashed_at->copy()->addSeconds(4));$next=$this->snap($s);$this->assertNotSame($r->round_public_id,$next['currentRound']['id']);$before=$this->financeHash();$this->assertSame($win['transactions'],$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'new-cashout-key')['transactions']);$this->assertSame($before,$this->financeHash());$this->assertSame(2,InternalGameCrashRound::count());
  $b=$this->bet($s,1,'new-round-bet');$r=$this->phase($s);$this->travelTo($r->crashed_at);$before=$this->financeHash();$this->reject(fn()=>$this->svc()->cashout($s->session_token,$this->player,$b['roundId'],'at-crash'));$this->assertSame('settled_loss',InternalGameRound::where('round_id',$b['roundId'])->value('status'));$this->travelTo($r->crashed_at->copy()->addSeconds(5));$next=$this->snap($s);$this->phase($s);$this->reject(fn()=>$this->svc()->cashout($s->session_token,$this->player,$b['roundId'],'old-bet-new-flight'));$this->assertSame($before,$this->financeHash());$this->reconcileBlackjack();}
 public function test_cashout_replay_refund_provenance_and_demo_refund_once():void{foreach([false,true]as $demo){$s=$this->open('sky-rush',$demo);$a=$this->bet($s);$this->phase($s);$win=$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'cashout');$before=$this->financeHash();$this->assertSame($win,$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'cashout'));$this->reject(fn()=>$this->svc()->refund($a['roundId'],'win-refund',$this->operator));$this->assertSame($before,$this->financeHash());$s=$this->open('orbit-x',$demo);$a=$this->bet($s);$this->assertSame('refunded',$this->svc()->refund($a['roundId'],'refund',$this->operator)['result']);$before=$this->financeHash();$this->assertSame('already_refunded',$this->svc()->refund($a['roundId'],'refund-again',$this->operator)['result']);$this->assertSame($before,$this->financeHash());$this->reject(fn()=>$this->bet($s,1,'same-refunded-lane'));$this->phase($s);$this->reject(fn()=>$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'refunded-cashout'));$this->travelTo(now()->addMinute());}$this->reconcileBlackjack();}
 public function test_ledger_failure_rolls_back_bet_cashout_refund_atomically():void{foreach(['bet','cashout','refund']as $action){$s=$this->open('sky-rush');$a=$action==='bet'?null:$this->bet($s,1,'initial-'.$action);if($action==='cashout')$this->phase($s);$before=$this->financeHash();$ledger=\Mockery::mock(InternalGameLedgerAuditService::class);$ledger->shouldReceive('recordDecimal')->once()->andThrow(new \RuntimeException('Injected crash ledger failure'));$this->app->instance(InternalGameLedgerAuditService::class,$ledger);try{match($action){'bet'=>$this->bet($s,2,'ledger-failure'),'cashout'=>$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'ledger-failure'),'refund'=>$this->svc()->refund($a['roundId'],'ledger-failure',$this->operator)};$this->fail('Expected failure');}catch(\RuntimeException $e){$this->assertSame('Injected crash ledger failure',$e->getMessage());}$this->assertSame($before,$this->financeHash());$this->app->forgetInstance(InternalGameLedgerAuditService::class);$this->travelTo(now()->addMinute());}$this->reconcileBlackjack();}
 public function test_audit_failure_rolls_back_funded_bet_cashout_and_refund():void{foreach(['bet','cashout','refund']as $action){$s=$this->open('sky-rush');$a=$action==='bet'?null:$this->bet($s,1,'audit-initial-'.$action);if($action==='cashout')$this->phase($s);$before=$this->financeHash();$realAudit=new \App\Services\InternalGames\InternalGameAuditService;$audit=\Mockery::mock(\App\Services\InternalGames\InternalGameAuditService::class)->makePartial();$event=match($action){'bet'=>'internal_game.crash.bet.accepted','cashout'=>'internal_game.crash.cashout.paid','refund'=>'internal_game.round.refunded'};$audit->shouldReceive('logRound')->andReturnUsing(function($session,$round,$name,$payload=[],$status='info')use($event,$realAudit){if($name===$event)throw new \RuntimeException('Injected crash audit failure');$realAudit->logRound($session,$round,$name,$payload,$status);});$this->app->instance(\App\Services\InternalGames\InternalGameAuditService::class,$audit);try{match($action){'bet'=>$this->bet($s,2,'audit-failure'),'cashout'=>$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'audit-failure'),'refund'=>$this->svc()->refund($a['roundId'],'audit-failure',$this->operator)};$this->fail('Expected audit rollback');}catch(\RuntimeException $e){$this->assertSame('Injected crash audit failure',$e->getMessage());}$this->assertSame($before,$this->financeHash());$this->app->forgetInstance(\App\Services\InternalGames\InternalGameAuditService::class);$this->travelTo(now()->addMinute());}$this->reconcileBlackjack();}
 public function test_decimal_canonical_balance_survives_original_cent_precision_payout():void{$this->credit('0.01','cent-precision');$s=$this->open();$a=$this->bet($s);$this->assertSame('490.01000000',$this->wallet->fresh()->available_balance);$this->phase($s);$win=$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'precise-win');$this->assertTrue(\Brick\Math\BigDecimal::of('490.01')->plus((string)$win['cashoutAmount'])->isEqualTo($win['balanceExact']));$this->reconcileBlackjack();}
 public function test_insufficiency_invalid_lane_stake_missing_and_borrowed_debit_do_not_write_money():void{$s=$this->open();$before=$this->financeHash();$this->reject(fn()=>$this->bet($s,3),422);$this->reject(fn()=>$this->bet($s,1,'bad-stake',11),422);app(\App\Services\Finance\ManualFinanceOverrideService::class)->execute(['operation_id'=>'crash-debit-zero','customer_id'=>$this->player->id,'wallet_account_id'=>$this->wallet->id,'currency'=>'TRY','economic_action'=>'manual_debit','external_resolution'=>'manual_operator_decision','amount'=>'500','reason'=>'Synthetic insufficient balance test','evidence_reference'=>'local-test'],$this->operator);$this->reject(fn()=>$this->bet($s));$this->credit('500','crash-restore');$a=$this->bet($s);$b=$this->bet($s,2,'other-lane');$row=InternalGameRound::where('round_id',$a['roundId'])->firstOrFail();$row->update(['debit_transaction_id'=>null]);$this->phase($s);$before=$this->financeHash();$this->reject(fn()=>$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'unfunded'));$this->reject(fn()=>$this->svc()->refund($a['roundId'],'unfunded',$this->operator));$row->update(['debit_transaction_id'=>InternalGameRound::where('round_id',$b['roundId'])->value('debit_transaction_id')]);$this->reject(fn()=>$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'borrowed'));$this->reject(fn()=>$this->svc()->refund($a['roundId'],'borrowed',$this->operator));$this->assertSame($before,$this->financeHash());}
 public function test_non_successful_or_non_bet_debit_is_not_cashout_or_refund_authority():void{$s=$this->open();$a=$this->bet($s);$this->phase($s);$row=InternalGameRound::where('round_id',$a['roundId'])->firstOrFail();foreach([['status'=>\App\Enum\TransactionStatusEnum::Pending],['action'=>\App\Enum\TransactionActionEnum::Win]]as $fault){DB::table('cms_user_transactions')->where('id',$row->debit_transaction_id)->update($fault);$before=$this->financeHash();$this->reject(fn()=>$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'invalid-debit'));$this->reject(fn()=>$this->svc()->refund($a['roundId'],'invalid-debit',$this->operator));$this->assertSame($before,$this->financeHash());DB::table('cms_user_transactions')->where('id',$row->debit_transaction_id)->update(['status'=>\App\Enum\TransactionStatusEnum::Success,'action'=>\App\Enum\TransactionActionEnum::Bet]);}$this->reconcileBlackjack();}
 public function test_wallet_currency_is_pinned_and_open_crash_round_blocks_wallet_switch():void{$s=$this->open();$a=$this->bet($s);$usd=DB::transaction(fn()=>app(\App\Services\Wallet\AssetWalletService::class)->ensurePrimaryBalanceWallet($this->player,'USD',true));$before=$this->financeHash();try{app(\App\Services\Wallet\ActiveWalletService::class)->switch($this->player,$usd->id);$this->fail('Open crash bet must block wallet change');}catch(\App\Services\Wallet\Exceptions\ActiveWalletChangeBlockedException $e){$this->assertStringContainsString('open_internal_game_round',json_encode($e->reasons()));}$this->assertSame($before,$this->financeHash());$this->phase($s);$win=$this->svc()->cashout($s->session_token,$this->player,$a['roundId'],'pinned-currency-cashout');$tx=CmsUserTransaction::where('transactionId',$win['transactions']['win'])->firstOrFail();$this->assertSame('TRY',$tx->currency);$this->assertSame($this->wallet->id,$tx->source_wallet_account_id);$this->assertSame('0.00000000',$usd->fresh()->available_balance);$this->reconcileBlackjack();}
 public function test_account_browser_expiry_maintenance_closed_product_boundaries():void{$s=$this->open();$a=$this->bet($s);$before=$this->financeHash();$other=$this->player->replicate();$other->username='crash_other';$other->email='crash-other@example.invalid';$other->save();$before=$this->financeHash();$this->reject(fn()=>$this->svc()->snapshot($s->session_token,$other),403);$this->browserRequest()->session()->regenerate();$this->reject(fn()=>$this->snap($s),403);$s->update(['launch_payload'=>array_merge($s->launch_payload,['dice_browser_hash'=>hash('sha256',request()->session()->getId())])]);$s->update(['expires_at'=>now()->subSecond()]);$this->reject(fn()=>$this->snap($s),410);$s->update(['expires_at'=>now()->addMinute()]);$s->game->update(['is_maintenance'=>true]);$this->reject(fn()=>$this->snap($s),503);$s->game->update(['is_maintenance'=>false,'status'=>'passive']);$this->reject(fn()=>$this->snap($s),404);$s->game->update(['status'=>'active']);config(['product_wallets.products.internal_games.supported_assets'=>['USD']]);$this->rejectProductBet($s);$this->assertSame($before,$this->financeHash());}
 private function rejectProductBet($s):void{try{$this->bet($s,2,'closed-product');$this->fail('Expected unsupported wallet');}catch(\App\Services\Wallet\Exceptions\UnsupportedProductWalletException $e){$this->assertSame('unsupported_wallet',$e->details()['reason_code']);}}
}
